#include "rbtree.h"
#include <stdlib.h>
#include <string.h>

/* Sole allocation path (CLAUDE.md routing rule). Weak so a test build (or a
 * future assignment) can link in a strong override for a custom allocator. */
__attribute__((weak)) void *rb_malloc(size_t size)
{
    return malloc(size);
}

__attribute__((weak)) void rb_free(void *ptr)
{
    free(ptr);
}

typedef struct rbnode {
    char *key;               /* owned copy; NULL on the nil sentinel */
    void *value;              /* owned iff value_free != NULL */
    struct rbnode *left;
    struct rbnode *right;
    struct rbnode *parent;
    enum { RB_RED, RB_BLACK } color;
} rbnode_t;

struct rbtree {
    rbnode_t *root;           /* == nil when empty */
    rbnode_t *nil;            /* shared black sentinel leaf; not counted in size */
    size_t size;
    rb_value_free_fn value_free;
};

rbtree_t *rb_create(rb_value_free_fn value_free)
{
    rbtree_t *t = rb_malloc(sizeof *t);
    if (!t)
        return NULL;                 /* nothing allocated yet, nothing to free */

    rbnode_t *nil = rb_malloc(sizeof *nil);
    if (!nil)
        goto cleanup_tree;           /* second alloc failed, unwind the first */

    nil->color  = RB_BLACK;
    nil->key    = NULL;
    nil->value  = NULL;
    nil->left = nil->right = nil->parent = nil;

    t->nil        = nil;
    t->root        = nil;
    t->size        = 0;
    t->value_free = value_free;
    return t;

cleanup_tree:
    rb_free(t);
    return NULL;
}

int rb_insert(rbtree_t *t, const char *key, void *value)
{
    (void)t;
    (void)key;
    (void)value;
    /* TODO: alloc node (goto-cleanup on either failure), BST insert against
     * nil leaves, red-black fixup, size++.
     * NOTE: copy the key via rb_malloc+memcpy, not strdup -- strdup calls
     * malloc directly, bypassing the CLAUDE.md allocation-routing rule. */
    return -1;
}

size_t rb_size(const rbtree_t *t)
{
    return t->size;
}

void *rb_find(const rbtree_t *t, const char *key)
{
    (void)t;
    (void)key;
    /* TODO: strcmp walk from root until node == t->nil. */
    return NULL;
}

void rb_foreach(const rbtree_t *t,
                void (*fn)(const char *key, void *value, void *ctx),
                void *ctx)
{
    (void)t;
    (void)fn;
    (void)ctx;
    /* TODO: in-order traversal, stopping at t->nil. */
}

int rb_validate(const rbtree_t *t)
{
    (void)t;
    /* TODO: BST order, red implies black children, equal black-height on
     * every root-to-nil path. */
    return -1;
}

void rb_destroy(rbtree_t *t)
{
    if (!t)
        return;
    /* TODO: once rb_insert lands real nodes, traverse and free each node's
     * key (and value, iff value_free is set) before freeing nil/t. Today
     * rb_create's only reachable output is an empty tree, so there are no
     * nodes/keys/values to walk yet. */
    rb_free(t->nil);
    rb_free(t);
}

content.text:
That's correct — `t` is a live, successfully-allocated object at that point (not null, not dangling), it just never got its `nil`/`root`/`size`/`value_free` fields set because the function bailed before reaching those lines. So it's not analogous to a Java null reference at all — it's more like a valid object that's only half-constructed, and `goto cleanup_tree` exists specifically to free that real allocation before it's lost (avoiding a leak, not a use-after-free).

You've got the beginner-tier concepts solid: allocation/free pairing, why cleanup order matters, and the specific difference between a dangling-pointer bug and a leak. Moving to **medium**.

**Medium Q1:** Look at the header comment for `rb_insert` (include/rbtree.h:9-13):

> Copies key (tree owns the copy). Takes ownership of value ONLY on success. ... Returns 0 on success, -1 on allocation failure (tree unchanged, value NOT consumed; caller still owns it).

Suppose a caller does this:

```c
char *v = rb_malloc(64);
strcpy(v, "hello");
if (rb_insert(t, "mykey", v) != 0) {
    // ???
}
```

What must go in the `// ???` branch, and why does the contract force that specific requirement onto the *caller* rather than having `rb_insert` handle it internally?

Solid across the board — the goto-cleanup design, ownership-on-failure, and the key/value asymmetry are all landing correctly. Moving to **hard**.

**Hard Q1:** Once `rb_insert` is implemented and the tree has real nodes, `rb_destroy`'s TODO comment (src/rbtree.c:106-109) says it needs to "traverse and free each node's key (and value, iff `value_free` is set) before freeing" — implying a recursive free over the whole tree, not just the two-object case you handled in Beginner Q2.

Suppose you write this recursively:

```c
static void free_subtree(rbtree_t *t, rbnode_t *n) {
    if (n == t->nil) return;
    free_subtree(t, n->left);
    free_subtree(t, n->right);
    rb_free(n->key);
    if (t->value_free) t->value_free(n->value);
    rb_free(n);
}
```

Is the *order* of these five lines (recurse-left, recurse-right, free-key, free-value, free-node) load-bearing, or could some of them be reordered safely? Pick one specific reordering that *would* break something, and explain what breaks.

